RED.autocomplete = (function () {
    function init() {
        RED.events.on('nodes:add', function(n) {
            console.log("Adding node:", n)
            // TODO" work out why n.x and n.y are undefined at this point?
            RED.comms.send('nodes/add', n);
        })
        
        RED.events.on('nodes:remove', function(n) {
            RED.comms.send('nodes/remove', n);
        })

        RED.comms.subscribe('autocomplete/#', (topic, msg) => {
            console.log('recv', topic, msg)
            if (topic === 'autocomplete/suggestion') {
                const suggestions = msg.suggestions;
                if (suggestions.length > 0 && suggestions[0].length > 0) {
                    const suggestion = suggestions[0];
                    console.log("Suggestion:", suggestion);
                    const node = suggestion[0]
                    var node_def = RED.nodes.getType(node.type);
                    console.log("Node definition:", node_def);
                    node._def = node_def;
                    console.log("Adding node:", node);
                    // TODO: draw the suggestion in "ghost" mode in the editor
                    RED.nodes.add(node);
                    RED.nodes.dirty(true);
                    RED.view.redraw(true);
                }
            }
        })
    }
    return {
        init: init
    };
})();